<?php
/**
 * MyBills - from docs/handover/artifact-source/MyBills.dc.html (scripts/sl_convert.py), bound to my_bills.php.
 * Shell page: yes
 * Data contract ($d): see sl_billsData() in views/sl/data/portal.php
 *   locker, filter, bills[{kind,cid|oid,no,sub,money,balMoney,settled,due,ghs}], owing, owingN, owingGhs, paidY, billedY, paidPct, settledN, bars[], top, mid, avg, canPay, gateway, consolidated
 */
if (!isset($d)) { $d = []; }
$f = sl_get($d, 'filter', 'owing');
$canOnline = sl_get($d, 'canPay') && sl_get($d, 'gateway') && sl_get($d, 'consolidated');
?>
<div class="sl-head"><div><h1 class="sl-title" style="font-size:20px">My bills</h1><p class="sl-lede">Locker <?= sl_v($d, 'locker') ?> · <?= $canOnline ? 'pay online or at the office' : 'pay at the office or with your account manager' ?></p></div><div class="row g8 wrap"><form class="ov-seg" method="get" action="<?= sl_route('MyBills') ?>"><?php foreach (['all' => 'All', 'owing' => 'Owing', 'settled' => 'Settled'] as $k => $l): ?><button type="submit" name="filter" value="<?= $k ?>" class="<?= $f === $k ? 'on' : '' ?>"><?= $l ?></button><?php endforeach; ?></form><?php if ($canOnline && (int) sl_get($d, 'owingN') > 0): ?><a class="sl-btn ghost" href="<?= sl_route('PayCheckout') ?>"><i class="ic ic-sm i-check" aria-hidden="true"></i>Choose packages to pay</a><?php endif; ?><?php if ($canOnline && (float) sl_get($d, 'owingGhs') > 0): ?><a class="sl-btn" href="<?= sl_route('PayCheckout') ?>"><i class="ic ic-sm i-card" aria-hidden="true"></i>Pay GHS <?= h(number_format((float) sl_get($d, 'owingGhs'), 2)) ?></a><?php endif; ?></div></div>
<div class="grid cols3"><a class="ov-card" href="<?= h(sl_url(['filter' => 'owing'])) ?>"><div class="hd"><span><i class="ic ic-sm i-receipt" aria-hidden="true"></i>Owing</span><i class="ic ic-sm i-right" aria-hidden="true"></i></div><div class="fig"><?= sl_v($d, 'owing') ?> <i>/ <?= (int) sl_get($d, 'owingN') ?> bill<?= (int) sl_get($d, 'owingN') === 1 ? '' : 's' ?></i></div><div class="sl-ticks r" role="img" aria-label="<?= 100 - (int) sl_get($d, 'paidPct') ?>% unpaid"><i style="width:<?= 100 - (int) sl_get($d, 'paidPct') ?>%"></i></div><div class="ft"><?= sl_get($d, 'dueDate') ? 'Next due ' . sl_v($d, 'dueDate') : 'Nothing overdue' ?></div></a><a class="ov-card" href="<?= h(sl_url(['filter' => 'settled'])) ?>"><div class="hd"><span><i class="ic ic-sm i-check" aria-hidden="true"></i>Paid this year</span><i class="ic ic-sm i-right" aria-hidden="true"></i></div><div class="fig"><?= sl_v($d, 'paidY') ?> <i>/ <?= sl_v($d, 'billedY') ?> billed</i></div><div class="sl-ticks" role="img" aria-label="<?= (int) sl_get($d, 'paidPct') ?>%"><i style="width:<?= (int) sl_get($d, 'paidPct') ?>%"></i></div><div class="ft"><?= (int) sl_get($d, 'settledN') ?> bills settled</div></a><a class="ov-card" href="<?= sl_route('QuoteCalculator') ?>"><div class="hd"><span><i class="ic ic-sm i-tag" aria-hidden="true"></i>Average month</span><i class="ic ic-sm i-right" aria-hidden="true"></i></div><div class="fig"><?= sl_v($d, 'avg') ?> <i>last 12 months</i></div><div class="sl-ticks y" role="img" aria-label="average"><i style="width:<?= sl_pct((float) preg_replace('/[^0-9.]/', '', (string) sl_get($d, 'avg')), max(1, (float) preg_replace('/[^0-9.]/', '', (string) sl_get($d, 'top')))) ?>%"></i></div><div class="ft">Check prices before you ship</div></a></div>
<section class="sl-card col g8"><div class="sl-ch" style="margin:0"><h2 class="sl-ct">What you spent</h2><span class="mut sm">12 months</span></div><div class="ov-avg">Avg <b><?= sl_v($d, 'avg') ?> / month</b></div><svg class="ov-chart" viewBox="0 0 1040 200" style="width:100%;height:auto" role="img" aria-label="Monthly spend over the year"><line x1="44" y1="170.0" x2="1030" y2="170.0" stroke="var(--line)" stroke-dasharray="0"></line><text x="36" y="174.0" text-anchor="end">0</text><line x1="44" y1="97" x2="1030" y2="97" stroke="var(--line)" stroke-dasharray="3 4"></line><text x="36" y="101" text-anchor="end"><?= sl_v($d, 'mid') ?></text><line x1="44" y1="24" x2="1030" y2="24" stroke="var(--line)" stroke-dasharray="3 4"></line><text x="36" y="28" text-anchor="end"><?= sl_v($d, 'top') ?></text><?php foreach ((array) sl_get($d, 'bars', []) as $b): ?><rect x="<?= $b['x'] ?>" y="<?= $b['y'] ?>" width="26.0" height="<?= max(0, $b['h']) ?>" rx="5" fill="<?= $b['now'] ? '#ECEAE5' : '#E9E7E1' ?>"<?= $b['now'] ? ' stroke="#D9D7D0"' : '' ?>><title><?= h($b['l'] . ': ' . $b['v']) ?></title></rect><text x="<?= $b['x'] + 13 ?>" y="192" text-anchor="middle"><?= h($b['l']) ?></text><?php endforeach; ?></svg></section>
<section class="sl-card flush">
<?php foreach ((array) sl_get($d, 'bills', []) as $b): ?>
<div class="ov-row" style="padding:0 18px;min-height:68px"><span class="sl-tile"><i class="ic ic-sm i-file" aria-hidden="true"></i></span><span class="grow col"><span><span class="mono fw5"><?= h($b['no']) ?></span> <?php if ($b['settled']): ?><span class="ov-pill ok">Paid</span><?php elseif (!empty($b['due'])): ?><span class="ov-pill bad">Due <?= h($b['due']) ?></span><?php else: ?><span class="ov-pill bad">Owing <?= h($b['balMoney']) ?></span><?php endif; ?></span><span class="mut sm"><?= h($b['sub']) ?></span></span><span class="mono fw5"><?= h($b['money']) ?></span>
<?php if ($b['settled']): ?>
<?php if ($b['kind'] === 'order'): ?><a class="sl-btn sm ghost" href="<?= h(sl_route('ShipmentDetail', ['id' => $b['oid']])) ?>">Details</a><?php endif; ?>
<?php elseif ($b['kind'] === 'consol' && $canOnline): ?><a class="sl-btn sm" href="<?= h(sl_route('PayCheckout', ['cid' => $b['cid']])) ?>">Pay now</a>
<?php else: ?><a class="sl-btn sm ghost" href="<?= h($b['kind'] === 'order' ? sl_route('ShipmentDetail', ['id' => $b['oid']]) : sl_route('PayCheckout', ['cid' => $b['cid'] ?? 0])) ?>" title="Pay at the office or with your account manager">How to pay</a><?php endif; ?>
</div>
<?php endforeach; ?>
<?php if (!sl_get($d, 'bills')): ?><div class="sl-empty mut sm" style="padding:24px 18px"><?= $f === 'settled' ? 'No settled bills yet.' : ($f === 'owing' ? 'You owe nothing. Thank you!' : 'No bills yet.') ?></div><?php endif; ?>
</section>
<?php if (!$canOnline): ?><div class="sl-banner info"><i class="ic ic-sm i-info" aria-hidden="true"></i><span><?= !sl_get($d, 'consolidated') ? 'Online payment is available for consolidated bills once billing is set up on this installation.' : (!sl_get($d, 'gateway') ? 'Online payment is switched off right now. Please pay at the office.' : 'Your account cannot pay online. Ask us to enable it.') ?></span></div><?php endif; ?>
